class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        s = list(word)
        res = 0

        i = 1
        while i < n:
            if (abs(ord(s[i]) - ord(s[i-1])) <= 1):
                res += 1
                # Change s[i] to something not almost-equal to s[i-1] or s[i+1] (if exists)
                for c in range(26):
                    newc = chr(ord('a') + c)
                    ok = True
                    if abs(ord(newc) - ord(s[i-1])) <= 1:
                        ok = False
                    if i+1 < n and abs(ord(newc) - ord(s[i+1])) <= 1:
                        ok = False
                    if ok:
                        s[i] = newc
                        break
                # After changing, skip to i+2, because now (i-1,i) isn't almost-equal anymore
                i += 2
            else:
                i += 1
        return res
